RockCommerce.component("rcproduct",{amount:1,amountInput:!1,maxamount:1,minamount:1,updateTimer:!1,price:0,money:null,init(){RockCommerce.addComponent(this);this.money=new RockMoney(this.$el.getAttribute("rc-price"));this.minamount=parseInt(this.$rcattr("rc-minamount")||RockCommerce.config.minamount);this.initAmount();this.$watch("amount",this.update.bind(this));this.maxamount=parseInt(this.$rcattr("rc-maxamount")||RockCommerce.config.maxamount);document.addEventListener("RockCommerce:ready",()=>{this.loadProductConfig();this.update()})},___addToCart(){RockCommerce.cart.addItem({pid:this.$rcpid,amount:this.amount,variation:this.variationString(!1,!1),})},getVariation(id){const selector=`[x-data=rcvariation][rc-pid="${id}"]`;const varEl=this.$root.querySelector(selector);return RockCommerce.getComponent(varEl)},initAmount(){this.amountInput=this.$el.querySelector("[x-model=amount]");this.amount=parseInt(this.amountInput.value||this.minamount);if(!this.amountInput)return;this.amountInput.addEventListener("focus",(e)=>{e.target.select()})},loadProductConfig(){const product=RockCommerce.products[0];if(!product)return;let hash=window.location.hash.substring(1).replace(/-/g,"&");hash=hash.replace(/:/g,"=");const urlParams=new URLSearchParams(hash);if(urlParams.has("amount")){const amount=parseInt(urlParams.get("amount"),10);if(!isNaN(amount))product.amount=amount}
const variations=product.variations||[];variations.forEach((variation)=>{const varID=variation.$rcpid;if(urlParams.has(varID)){variation.disableAll();const options=urlParams.get(varID).split(",");options.forEach((pid)=>{const option=RockCommerce.getComponentFromPid(pid);if(option)option.enable();})}})},minus(){if(this.amount-1<this.minamount)return(this.amount=this.minamount);if(this.amount-1>this.maxamount)return(this.amount=this.maxamount);this.amount--},plus(){if(this.amount+1>this.maxamount)return(this.amount=this.maxamount);if(this.amount+1<this.minamount)return(this.amount=this.minamount);this.amount++},___priceInit(money){return money},___priceVar(money){this.variations.forEach((variation)=>{if(typeof variation=="undefined")return;variation.options(!0).forEach((option)=>{money=money.plus(option.money.float())})});return money},___priceTotal(money){return money.times(this.amount)},update(){RockCommerce.debounce("rcproduct-update",()=>{let amount=this.amount;if(amount>this.maxamount)amount=this.maxamount;else if(amount<this.minamount)amount=this.minamount;this.amount=amount;let money=this.money;money=this.priceInit(money);money=this.priceVar(money);money=this.priceTotal(money);this.price=money.format();this.updateUrl()})},updateUrl(){if(!this.$rcattr("rc-updateUrl"))return;let str=this.variationString();let url=new URL(window.location);url.hash=str;history.replaceState(null,"",url)},variationObject(){let obj={};obj.amount=this.amount;this.variations.forEach((variation)=>{obj[variation.$rcpid]=variation.optionsString});return obj},get variations(){return Array.from(this.$root.querySelectorAll("[x-data=rcvariation]")).map((el)=>{return RockCommerce.getComponent(el)})},variationString(includeAmount=!0,includeHash=!0){let obj=this.variationObject();if(!includeAmount)delete obj.amount;let str="";Object.keys(obj).forEach((key)=>{const value=obj[key]+"";if(!value)return;str+=`-${key}:${value}`});str=includeHash?"#"+str.substring(1):str.substring(1);return str},})